1	package world
2	
3	import (
4		"errors"
5		"fmt"
6		"os"
7		"syscall"
8	)
9	
10	// Record 是一次成功保存留下的、可供读取的记录。
11	type Record struct {
12		// ID 是记录标识。
13		ID RecordID
14		// Parent 是父记录标识。只有直接建立的槽首记录没有父记录（为空）；
15		// 分支槽的首条记录以来源槽记录为父，因此“槽首记录”并不等于
16		// “没有父记录”。
17		Parent RecordID
18		// SlotFirst 表示这是其所在槽的首条记录（直接建立的根记录，或从
19		// 其他槽分出的分支首记录）；它不代表 Parent 一定为空。
20		SlotFirst bool
21		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
22		State State
23	}
24	
25	func acquireSharedLock(dir string) (*fileLock, error) {
26		path := dir + "/lock"
27		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
28		if err != nil {
29			return nil, err
30		}
31		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
32			f.Close()
33			return nil, err
34		}
35		return &fileLock{f: f}, nil
36	}
37	
38	// loadAndVerifyLocked 读取记录文件，校验其文本编码（无效 UTF-8 字节与
39	// 不成对的 Unicode 代理项转义一律损坏）、记录格式版本、内容校验和（校验和
40	// 已包含父记录关系）、父记录是否存在，以及世界数据是否自洽。
41	//
42	// 文本编码检查在解析前按原始字节进行：encoding/json 会把无效字节与不成对
43	// 的代理项转义悄悄改写成替换字符“�”，若原记录本就含有合法的“�”，改写后
44	// 的文本甚至可能仍通过校验和检查，因此这类记录即使替换后的世界状态合法、
45	// 校验和匹配、规则版本也被接受，仍按损坏拒绝，绝不用替换字符补齐后交付。
46	//
47	// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
48	// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
49	// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
50	// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
51	// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
52	// CorruptError，绝不报成 VersionRejectedError。
53	//
54	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
55	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
56	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
57	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
58		env, err := loadRecord(recordPath(a.dir, id))
59		if err != nil {
60			if errors.Is(err, os.ErrNotExist) {
61				return nil, &NotFoundError{Record: id}
62			}
63			return nil, &CorruptError{Record: id, Reason: err.Error()}
64		}
65		if env.ID != id {
66			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
67		}
68		if env.Format != recordFormatVersion {
69			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
70		}
71		if got := computeChecksum(env); got != env.Checksum {
72			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
73		}
74		// 父记录关系必须落到一个真实存在的记录上。
75		if env.Parent != "" {
76			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
77				if errors.Is(err, os.ErrNotExist) {
78					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
79				}
80				return nil, err
81			}
82		}
83		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
84		// 其余状态合法，也按损坏处理，不自动把时间改成零。
85		if env.State.Time < 0 {
86			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
87		}
88		if err := validateInitialData(InitialData{
89			Seed:       env.State.Seed,
90			Rules:      env.State.Rules,
91			Characters: env.State.Characters,
92		}); err != nil {
93			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
94		}
95		return env, nil
96	}
97	
98	func versionAccepted(version string, accepted []string) bool {
99		for _, v := range accepted {
100			if v == version {
101				return true
102			}
103		}
104		return false
105	}
106	
107	func envToRecord(env *envelope) Record {
108		return Record{
109			ID:        env.ID,
110			Parent:    env.Parent,
111			SlotFirst: env.SlotFirst,
112			State:     cloneState(env.State),
113		}
114	}
115	
116	// Latest 读取槽当前最新记录。
117	//
118	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
119	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（文本编码或
120	// Unicode 转义损坏、格式版本不受支持、校验和不符、父记录缺失、无法解析、
121	// 时间片为负）时返回 *CorruptError。文本损坏与格式问题都先于版本判断：
122	// 即使版本不被接受，损坏的记录也报损坏而不报版本拒绝。
123	// 读取不会改写存档。
124	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
125		if !validSlotName(slot) {
126			return Record{}, &NotFoundError{Slot: slot}
127		}
128		lock, err := acquireSharedLock(a.dir)
129		if err != nil {
130			return Record{}, err
131		}
132		defer lock.release()
133	
134		id, err := a.readLatestLocked(slot)
135		if err != nil {
136			return Record{}, err
137		}
138		env, err := a.loadAndVerifyLocked(id)
139		if err != nil {
140			if ce, ok := err.(*CorruptError); ok {
141				ce.Slot = slot
142			}
143			return Record{}, err
144		}
145		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
146			return Record{}, &VersionRejectedError{
147				Slot:     slot,
148				Record:   id,
149				Version:  env.State.Rules.Version,
150				Accepted: append([]string(nil), acceptedVersions...),
151			}
152		}
153		return envToRecord(env), nil
154	}
155	
156	// Record 按标识读取槽的一份历史记录（覆盖、升级或确认恢复之后，较早的
157	// 旧记录仍可按其标识读取）。
158	//
159	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
160	// 且记录必须属于该槽的历史链。acceptedVersions 必须显式给出调用方可以
161	// 接受的规则版本：记录完好但版本不在集合内时返回 *VersionRejectedError。
162	// 读取不会切换槽当前记录，不会修补记录，也不会替换记录中的规则版本。
163	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
164		if !validSlotName(slot) {
165			return Record{}, &NotFoundError{Slot: slot}
166		}
167		lock, err := acquireSharedLock(a.dir)
168		if err != nil {
169			return Record{}, err
170		}
171		defer lock.release()
172	
173		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
174			return Record{}, err
175		}
176		env, err := a.loadAndVerifyLocked(id)
177		if err != nil {
178			if ce, ok := err.(*CorruptError); ok {
179				ce.Slot = slot
180			}
181			return Record{}, err
182		}
183		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
184			return Record{}, &VersionRejectedError{
185				Slot:     slot,
186				Record:   id,
187				Version:  env.State.Rules.Version,
188				Accepted: append([]string(nil), acceptedVersions...),
189			}
190		}
191		return envToRecord(env), nil
192	}
193	
194	// History 浏览槽已经保存生效的历史，返回每条记录的元信息（记录标识、
195	// 父标识、槽首标记、规则版本），供先浏览、再用 [Archive.Record] 按标识
196	// 读取完整世界。
197	//
198	// 次序按该槽“保存生效的先后”排列：最近一次成功保存的记录在最前，槽首
199	// 记录在末尾。它既不按记录里的世界时间片排序，也不按记录文件的修改时间
200	// 排序——确认恢复允许时间片回到较早来源的时刻，那次保存产生的新记录仍排
201	// 在最前，而原先已经生效的其他保存按原次序保留。
202	//
203	// 父标识表示“这条记录由哪一次保存承接而来”，与列表次序是两回事。槽首
204	// 标记不能统一解释成“父标识为空”：只有直接建立的槽首记录没有父记录；
205	// 分支槽的首条记录虽然标记为槽首，却以来源槽的那条记录为父记录。分支槽
206	// 只列分支自身保存生效的记录，不会因为分支首记录的父指向来源槽，就把
207	// 来源槽的历史补进列表。
208	//
209	// 列表只做完整性检查，不筛选规则版本：History 没有可接受版本参数，一份
210	// 记录只要确实保存生效且通过与 Record 一致的完整性检查——标识与文件一致、
211	// 记录格式受支持、内容校验和正确（含父记录关系）、世界状态合法、直接父
212	// 记录文件存在——即使规则版本较旧或陌生也照常列出。因此“出现在列表里”
213	// 只说明记录完好，不保证调用方立即可用：用 Record 读取时仍必须显式给出
214	// 可接受版本集合，版本不被接受会得到 *VersionRejectedError，不能据此认为
215	// 历史列错了。
216	//
217	// 带历史索引的槽中，单条损坏、缺失或无法解析的记录只被略过，列表继续
218	// 返回其余合格记录，最新或某条中间记录出问题不会让整个浏览失败；但直接
219	// 父记录文件被删除的子记录因不满足父关系要求也被略过，而父文件仍在、
220	// 只是内容损坏时，不因此略过自身完好的子记录。旧版本写出的无历史索引槽
221	// 沿校验通过的父链在内存中重建，只列仍能确认归属本槽的记录，重建在损坏
222	// 处停止，不能承诺越过损坏处继续寻找更老的记录。
223	//
224	// 槽存在但没有任何合格记录时，返回成功的非 nil 空列表；槽不存在返回
225	// *NotFoundError，槽指针无法解析返回 *CorruptError，三者互不等同，不能把
226	// 不存在或损坏当成空列表。浏览只做只读遍历，不切换槽当前记录、不修补或
227	// 删除记录、不改写历史与世界规则。
228	func (a *Archive) History(slot string) ([]RecordInfo, error) {
229		if !validSlotName(slot) {
230			return nil, &NotFoundError{Slot: slot}
231		}
232		lock, err := acquireSharedLock(a.dir)
233		if err != nil {
234			return nil, err
235		}
236		defer lock.release()
237	
238		history, err := a.slotHistoryLocked(slot)
239		if err != nil {
240			return nil, err
241		}
242		infos := make([]RecordInfo, 0, len(history))
243		for _, id := range history {
244			// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
245			// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
246			// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
247			env, verifyErr := a.loadAndVerifyLocked(id)
248			if verifyErr != nil {
249				continue
250			}
251			infos = append(infos, RecordInfo{
252				ID:        env.ID,
253				Parent:    env.Parent,
254				SlotFirst: env.SlotFirst,
255				Version:   env.State.Rules.Version,
256			})
257		}
258		return infos, nil
259	}
260	
261	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
262	// 版本可接受的已保存记录。
263	//
264	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
265	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
266	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
267	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
268	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
269	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
270	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
271	//
272	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
273	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
274	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
275	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
276	// 不会被选中。
277	//
278	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
279	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
280	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
281	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
282	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
283		if !validSlotName(slot) {
284			return Record{}, &NotFoundError{Slot: slot}
285		}
286		lock, err := acquireSharedLock(a.dir)
287		if err != nil {
288			return Record{}, err
289		}
290		defer lock.release()
291	
292		history, err := a.slotHistoryLocked(slot)
293		if err != nil {
294			return Record{}, err
295		}
296	
297		env, err := a.firstRecoverableLocked(history, acceptedVersions)
298		if err != nil {
299			var ue *UnrecoverableError
300			if errors.As(err, &ue) {
301				ue.Slot = slot
302			}
303			return Record{}, err
304		}
305		return envToRecord(env), nil
306	}
307	
308	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
309	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
310	//
311	// 文件缺失、截断、格式版本不受支持、校验和不符、记录标识不符、父关系异常、
312	// 时间片为负或世界状态不自洽的记录一律越过（不读其中的父标识或槽首标记）；
313	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
314	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
315	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
316	// 补全）。
317	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
318		var lastReason string
319		for _, id := range history {
320			env, verifyErr := a.loadAndVerifyLocked(id)
321			if verifyErr != nil {
322				lastReason = verifyErr.Error()
323				continue
324			}
325			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
326				lastReason = (&VersionRejectedError{
327					Record:  id,
328					Version: env.State.Rules.Version,
329				}).Error()
330				continue
331			}
332			return env, nil
333		}
334	
335		if lastReason == "" {
336			lastReason = "槽中没有任何可确认归属的历史记录"
337		}
338		return nil, &UnrecoverableError{Reason: lastReason}
339	}
