1	package world
2	
3	import (
4		"crypto/rand"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"io"
11		"os"
12		"path/filepath"
13		"unicode/utf8"
14	)
15	
16	// RecordID 是一次成功保存产生的、在同一存档目录内唯一的记录标识。
17	type RecordID string
18	
19	// archiveFormatVersion 是存档目录布局版本，写入目录标记中。
20	const archiveFormatVersion = 1
21	
22	// recordFormatVersion 是当前唯一支持的记录格式版本。记录格式与存档目录
23	// 布局版本是两个独立的编号：目录可打开不代表其中每条记录都能被理解，
24	// 格式编号不是该值的记录（缺失、零、负值或其他正整数）一律按损坏处理，
25	// 即使其校验和匹配、世界状态合法。
26	const recordFormatVersion = 1
27	
28	// envelope 是记录文件在磁盘上的完整编码。
29	type envelope struct {
30		// Format 是记录格式版本。
31		Format int `json:"format"`
32		// ID 是本条记录的唯一标识。
33		ID RecordID `json:"id"`
34		// Parent 是父记录标识；直接建立的槽首条记录为空。
35		Parent RecordID `json:"parent,omitempty"`
36		// SlotFirst 标记本条记录是否为其所在槽的首条记录
37		// （直接建立的根记录，或从其他槽分出的分支记录）。
38		SlotFirst bool `json:"slotFirst"`
39		// Checksum 是对（格式版本、ID、父记录、首记录标记、完整世界状态）
40		// 计算出的内容校验和，因此父记录关系也被纳入校验。
41		Checksum string `json:"checksum"`
42		// State 是完整世界数据：种子、规则与全部状态。
43		State State `json:"state"`
44	}
45	
46	// checksumPayload 是参与校验和计算的规范内容。
47	type checksumPayload struct {
48		Format    int      `json:"format"`
49		ID        RecordID `json:"id"`
50		Parent    RecordID `json:"parent"`
51		SlotFirst bool     `json:"slotFirst"`
52		State     State    `json:"state"`
53	}
54	
55	func computeChecksum(e *envelope) string {
56		p := checksumPayload{
57			Format:    e.Format,
58			ID:        e.ID,
59			Parent:    e.Parent,
60			SlotFirst: e.SlotFirst,
61			State:     e.State,
62		}
63		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
64		b, _ := json.Marshal(p)
65		sum := sha256.Sum256(b)
66		return hex.EncodeToString(sum[:])
67	}
68	
69	// newRecordID 产生目录内唯一的记录标识。
70	func newRecordID() (RecordID, error) {
71		var b [16]byte
72		if _, err := rand.Read(b[:]); err != nil {
73			return "", err
74		}
75		return RecordID("r" + hex.EncodeToString(b[:])), nil
76	}
77	
78	func recordPath(dir string, id RecordID) string {
79		return filepath.Join(dir, "records", string(id)+".json")
80	}
81	
82	// writeRecord 将一条记录以“先临时文件后原子改名”的方式落盘，
83	// 并校验目标文件名此前不存在，保证记录标识不会复用或混写。
84	func writeRecord(slotDir string, e *envelope) error {
85		final := recordPath(slotDir, e.ID)
86		data, err := json.MarshalIndent(e, "", "  ")
87		if err != nil {
88			return err
89		}
90	
91		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
92		f, err := os.OpenFile(final+".tmp",
93			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
94		if err != nil {
95			return err
96		}
97		tmpName := f.Name()
98		clean := true
99		defer func() {
100			if clean {
101				os.Remove(tmpName)
102			}
103		}()
104	
105		if _, err := f.Write(data); err != nil {
106			f.Close()
107			return err
108		}
109		if err := f.Sync(); err != nil {
110			f.Close()
111			return err
112		}
113		if err := f.Close(); err != nil {
114			return err
115		}
116		if err := os.Rename(tmpName, final); err != nil {
117			return err
118		}
119		clean = false
120		if err := syncDir(filepath.Dir(final)); err != nil {
121			return err
122		}
123		return nil
124	}
125	
126	// loadRecord 读取并解析一条记录文件，但不做校验。
127	//
128	// 解析前先做文本编码检查：encoding/json 会把记录中的无效 UTF-8 字节和
129	// 字符串值、对象键里不成对的 Unicode 代理项转义悄悄改写成替换字符“�”，
130	// 随后才做内容校验——若原记录本就含有合法的“�”，改写后的文本甚至可能
131	// 仍通过校验和检查，文件损坏便被掩盖。因此无效字节与不成对的代理项转义
132	// 必须在解析前按原始字节拒绝，整条记录视为损坏，绝不用替换字符补齐后
133	// 继续交付。
134	func loadRecord(path string) (*envelope, error) {
135		f, err := os.Open(path)
136		if err != nil {
137			return nil, err
138		}
139		defer f.Close()
140		data, err := io.ReadAll(f)
141		if err != nil {
142			return nil, err
143		}
144		if err := checkRecordText(data); err != nil {
145			return nil, err
146		}
147		var e envelope
148		if err := json.Unmarshal(data, &e); err != nil {
149			return nil, fmt.Errorf("记录无法解析: %w", err)
150		}
151		return &e, nil
152	}
153	
154	// checkRecordText 校验记录文件原始字节的文本编码：JSON 文本必须是合法
155	// UTF-8；字符串值与对象键中的 \uXXXX 转义若是代理项，必须完整配对——
156	// 高位代理项（D800–DBFF）后必须紧接一个低位代理项转义（DC00–DFFF），
157	// 低位代理项不得单独出现。合法内容不受影响：真实存在的“�”、正确配对
158	// 的代理项转义与同一字符的合法转义写法都照常接受；已经转义的反斜杠
159	// （\\）其后的 uD800 只是普通文字，不是代理项转义。
160	func checkRecordText(data []byte) error {
161		if !utf8.Valid(data) {
162			return errors.New("记录包含无效 UTF-8 字节，文本编码损坏")
163		}
164		// 只需定位字符串字面量并检查其中的 \u 转义；JSON 其余部分的合法性
165		// 由 json.Unmarshal 判断。data 已是合法 UTF-8，多字节字符中不可能
166		// 出现 '"' 或 '\\' 字节。
167		i := 0
168		for i < len(data) {
169			if data[i] != '"' {
170				i++
171				continue
172			}
173			i++ // 进入字符串字面量
174			for i < len(data) {
175				c := data[i]
176				if c == '"' {
177					i++
178					break
179				}
180				if c != '\\' {
181					i++
182					continue
183				}
184				// 转义序列：\\ 是已转义的反斜杠，其后的 uD800 只是普通文字。
185				i++
186				if i >= len(data) {
187					break // 截断的转义由 json.Unmarshal 报解析错误
188				}
189				esc := data[i]
190				i++
191				if esc != 'u' {
192					continue
193				}
194				if i+4 > len(data) {
195					break // 截断的转义由 json.Unmarshal 报解析错误
196				}
197				v, ok := hex4(data[i : i+4])
198				i += 4
199				if !ok {
200					continue // 非法十六进制由 json.Unmarshal 报解析错误
201				}
202				switch {
203				case v >= 0xD800 && v <= 0xDBFF:
204					// 高位代理项必须紧接一个低位代理项转义才完整。
205					if i+6 <= len(data) && data[i] == '\\' && data[i+1] == 'u' {
206						if lo, ok := hex4(data[i+2 : i+6]); ok && lo >= 0xDC00 && lo <= 0xDFFF {
207							i += 6
208							continue
209						}
210					}
211					return fmt.Errorf("记录包含未配对的高位代理项转义 \\u%04X，Unicode 转义损坏", v)
212				case v >= 0xDC00 && v <= 0xDFFF:
213					return fmt.Errorf("记录包含单独出现的低位代理项转义 \\u%04X，Unicode 转义损坏", v)
214				}
215			}
216		}
217		return nil
218	}
219	
220	// hex4 解析 4 位十六进制数字（\uXXXX 转义的码位部分）。
221	func hex4(b []byte) (int, bool) {
222		v := 0
223		for _, c := range b {
224			v <<= 4
225			switch {
226			case c >= '0' && c <= '9':
227				v |= int(c - '0')
228			case c >= 'a' && c <= 'f':
229				v |= int(c-'a') + 10
230			case c >= 'A' && c <= 'F':
231				v |= int(c-'A') + 10
232			default:
233				return 0, false
234			}
235		}
236		return v, true
237	}
