249	// 原子改名，保证崩溃后只会看到旧文件或新文件。
250	func writeAtomic(dir, name string, data []byte) error {
251		tmp := filepath.Join(dir, ".tmp-"+name+"-"+randomSuffix())
252		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
253		if err != nil {
254			return err
255		}
256		clean := true
257		defer func() {
258			if clean {
259				os.Remove(tmp)
260			}
261		}()
262		if _, err := f.Write(data); err != nil {
263			f.Close()
264			return err
265		}
266		if err := f.Sync(); err != nil {
267			f.Close()
268			return err
269		}
270		if err := f.Close(); err != nil {
271			return err
272		}
273		final := filepath.Join(dir, name)
274		if err := os.Rename(tmp, final); err != nil {
275			return err
276		}
277		clean = false
278		return syncDir(dir)
279	}
280	
281	func randomSuffix() string {
282		var b [8]byte
283		_, _ = rand.Read(b[:])
284		return hex.EncodeToString(b[:])
