13	// 字节或不成对的 Unicode 代理项转义），并按替换字符补齐后的解析结果重算
14	// 内容校验和写回，模拟“损坏文本被替换字符补齐后仍通过校验和检查”的记录：
15	// 替换后的世界状态合法、校验和匹配，只有按原始字节检查文本编码才能发现。
16	func rewriteRecordText(t *testing.T, a *Archive, id RecordID, from, to string) {
17		t.Helper()
18		path := recordPath(a.dir, id)
19		raw, err := os.ReadFile(path)
20		if err != nil {
21			t.Fatal(err)
22		}
23		var env envelope
24		if err := json.Unmarshal(raw, &env); err != nil {
25			t.Fatal(err)
26		}
27		oldSum := env.Checksum
28		if !strings.Contains(string(raw), from) {
29			t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
30		}
31		corrupted := strings.Replace(string(raw), from, to, 1)
32		// encoding/json 会把无效字节与不成对的代理项转义改写成替换字符，解析
33		// 仍然成功；按解析结果重算校验和，使损坏在校验和下被掩盖。
34		var cenv envelope
35		if err := json.Unmarshal([]byte(corrupted), &cenv); err != nil {
36			t.Fatalf("测试前提：损坏后的记录应仍可被 encoding/json 解析: %v", err)
37		}
38		corrupted = strings.Replace(corrupted, oldSum, computeChecksum(&cenv), 1)
39		if err := os.WriteFile(path, []byte(corrupted), 0o600); err != nil {
40			t.Fatal(err)
41		}
42	}
