44	// assertTextCorrupt 断言 err 是保留了被拒绝记录标识、且说明损坏类别
45	// （文本编码或 Unicode 转义）的 *CorruptError，而不是版本拒绝或其它错误。
46	func assertTextCorrupt(t *testing.T, err error, id RecordID, keyword string) {
47		t.Helper()
48		ce, ok := err.(*CorruptError)
49		if !ok {
50			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
51		}
52		if ce.Record != id {
53			t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
54		}
55		if !strings.Contains(ce.Error(), keyword) {
56			t.Fatalf("错误应说明损坏类别 %q: %v", keyword, ce)
57		}
58		if errors.As(err, new(*VersionRejectedError)) {
59			t.Fatalf("文本损坏不应报成版本拒绝: %v", err)
60		}
61	}
