63	// TestLatestAndRecordInvalidUTF8Corrupt 记录文件中出现无效 UTF-8 字节时，
64	// 即使替换字符补齐后的世界状态合法、校验和匹配、规则版本也被接受，Latest
65	// 与 Record 都必须把整条记录视为损坏，返回保留记录标识并说明文本编码损坏
66	// 的 *CorruptError；读取保持只读，不修补这份记录。
67	func TestLatestAndRecordInvalidUTF8Corrupt(t *testing.T) {
68		a, _ := newTestArchive(t)
69		ids := saveN(t, a, "s", 1) // r1 r0
70		// 角色标识中的无效字节：替换后是合法的 "he�ro"，状态自洽、校验和匹配。
71		rewriteRecordText(t, a, ids[0], `"ID": "hero"`, "\"ID\": \"he\xffro\"")
72		before := recordFileBytes(t, a, ids[0])
73	
74		_, err := a.Latest("s", []string{"v1"})
75		assertTextCorrupt(t, err, ids[0], "UTF-8")
76	
77		_, err = a.Record("s", ids[0], []string{"v1"})
