80		// 版本不被接受时同样报损坏，不报版本拒绝。
81		_, err = a.Latest("s", []string{"other"})
82		assertTextCorrupt(t, err, ids[0], "UTF-8")
83	
84		// 记录没有被悄悄修补或删除，槽指向不变。
85		if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
