98	// TestUnpairedSurrogateEscapeCorrupt 字符串值与对象键中不成对的 Unicode
99	// 代理项转义（高位未紧接合法低位、低位单独出现）都属于损坏：即使替换后的
100	// 状态合法、校验和匹配，也一律返回 *CorruptError。
101	func TestUnpairedSurrogateEscapeCorrupt(t *testing.T) {
102		cases := []struct {
103			name string
104			from string
105			to   string
106		}{
107			{"高位后接普通文字", `"ID": "hero"`, `"ID": "he\uD800ro"`},
108			{"高位在字符串末尾", `"ID": "hero"`, `"ID": "her\uD800"`},
