137	// TestHistorySkipsTextCorruptRecords 带历史索引的槽中，文本损坏的记录在
138	// 浏览时只被略过，其余完好记录仍按保存生效次序列出；恢复读取与恢复预览
139	// 选择本槽最近一份完整且版本可接受的记录，全部不可用时返回
140	// ErrUnrecoverable。浏览、读取与预览都不修补、删除或切换任何内容。
141	func TestHistorySkipsTextCorruptRecords(t *testing.T) {
142		a, _ := newTestArchive(t)
143		ids := saveN(t, a, "s", 2) // r2(time 2) r1(time 1) r0(time 0)
144		rewriteRecordText(t, a, ids[0], `"ID": "hero"`, `"ID": "he\uD800ro"`)
145		before := recordFileBytes(t, a, ids[0])
