154		}
155	
156		// 恢复读取与恢复预览选中最近一份完好且版本可接受的记录。
157		rec, err := a.RecoverLatest("s", []string{"v1"})
158		if err != nil {
159			t.Fatalf("RecoverLatest: %v", err)
160		}
161		if rec.ID != ids[1] || rec.State.Time != 1 {
162			t.Fatalf("应恢复 %s（时间片 1），得到 %s（时间片 %d）", ids[1], rec.ID, rec.State.Time)
163		}
164		pv, err := a.PreviewRecovery("s", []string{"v1"})
165		if err != nil {
166			t.Fatalf("PreviewRecovery: %v", err)
167		}
168		if pv.Current != ids[0] || pv.Source != ids[1] {
169			t.Fatalf("预览应为 current=%s source=%s，得到 current=%s source=%s",
170				ids[0], ids[1], pv.Current, pv.Source)
171		}
172	
173		// 全部记录都文本损坏时，恢复与预览返回 ErrUnrecoverable。
174		rewriteRecordText(t, a, ids[1], `"ID": "hero"`, `"ID": "he\uD800ro"`)
175		rewriteRecordText(t, a, ids[2], `"ID": "hero"`, `"ID": "he\uD800ro"`)
176		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
177			t.Fatalf("全部损坏应不可恢复，得到 %T: %v", err, err)
178		}
179		if _, err := a.PreviewRecovery("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
180			t.Fatalf("预览同样应不可恢复，得到 %T: %v", err, err)
181		}
182		if infos, err := a.History("s"); err != nil || len(infos) != 0 {
183			t.Fatalf("全部损坏时历史应为成功的空列表: %+v err=%v", infos, err)
184		}
185	
186		// 全程只读：受损文件未被修补或删除，槽当前指向不变。
187		if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
188			t.Fatal("浏览/恢复改写了文本损坏的记录")
189		}
190		if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
191			t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
192		}
193	}
194	
195	// TestLegalUnicodeTextStillReadable 合法文本的兼容性保留：真实存在的“�”、
196	// 中文与表情符号、正确配对的代理项转义、同一字符的合法转义写法以及已转义
197	// 反斜杠后的 uD800 普通文字都正常读回；仅改变缩进或转义写法的记录仍按
198	// 现有内容校验规则判断，不要求与最初保存的字节完全相同。
199	func TestLegalUnicodeTextStillReadable(t *testing.T) {
200		a, _ := newTestArchive(t)
201		w, err := NewWorld(InitialData{
202			Seed: 7,
203			Rules: Rules{
204				Version:     "v1",
205				Locations:   []string{"大厅", "院子"},
206				Edges:       []Edge{{From: "大厅", To: "院子"}},
207				ItemKinds:   []string{"金币"},
208				CarryLimits: map[string]int{"英雄😀": 3},
209			},
210			Characters: []Character{
211				{ID: "英雄😀", Location: "大厅", Items: []CharacterItem{{Item: "金币", Count: 1}}},
212				// 已转义的反斜杠后跟 uD800 只是普通文字，不是孤立代理项。
213				{ID: `名字\uD800`, Location: "院子"},
214				// 真实存在的替换字符是合法名称。
215				{ID: "替�身", Location: "院子"},
216			},
217		})
218		if err != nil {
219			t.Fatalf("NewWorld: %v", err)
220		}
221		want := w.Snapshot()
222		info, err := a.Save("s", w)
223		if err != nil {
224			t.Fatalf("Save: %v", err)
225		}
226	
227		// 把文件中的 😀 改写为正确配对的代理项转义、大厅改写为 \u5927\u5385：
228		// 解析内容不变，校验和仍然匹配，记录应照常可读。
229		path := recordPath(a.dir, info.ID)
230		raw, err := os.ReadFile(path)
231		if err != nil {
232			t.Fatal(err)
233		}
234		s := string(raw)
235		s = strings.ReplaceAll(s, "😀", `\uD83D\uDE00`)
236		s = strings.ReplaceAll(s, "大厅", `\u5927\u5385`)
237		if err := os.WriteFile(path, []byte(s), 0o600); err != nil {
238			t.Fatal(err)
239		}
240	
241		rec, err := a.Latest("s", []string{"v1"})
242		if err != nil {
243			t.Fatalf("合法转义写法的记录应可读: %v", err)
244		}
245		if !reflect.DeepEqual(rec.State, want) {
246			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
247		}
248	
249		// 仅改变缩进与空白也不影响内容校验。
250		compact, err := os.ReadFile(path)
251		if err != nil {
252			t.Fatal(err)
253		}
254		var env envelope
255		if err := json.Unmarshal(compact, &env); err != nil {
256			t.Fatal(err)
257		}
258		flat, err := json.Marshal(env)
259		if err != nil {
260			t.Fatal(err)
261		}
262		if err := os.WriteFile(path, flat, 0o600); err != nil {
263			t.Fatal(err)
264		}
265		rec2, err := a.Latest("s", []string{"v1"})
266		if err != nil {
267			t.Fatalf("仅改变格式的记录应可读: %v", err)
268		}
269		if !reflect.DeepEqual(rec2.State, want) {
270			t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec2.State, want)
271		}
272	}
