		t.Fatalf("全部损坏时历史应为成功的空列表: %+v err=%v", infos, err)
	}

	// 全程只读：受损文件未被修补或删除，槽当前指向不变。
	if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
		t.Fatal("浏览/恢复改写了名称重复的记录")
	}
