	if !reflect.DeepEqual(rec.State, want) {
		t.Fatalf("读回状态与保存前不一致:\n got %+v\nwant %+v", rec.State, want)
	}

	// 只改变缩进与字段排列（经 map 重新序列化）但内容未变的记录仍可读。
	var m map[string]any
	if err := json.Unmarshal([]byte(s), &m); err != nil {
